CREATE VIEW registry_source."business"
                 WITH (security_invoker=true, security_barrier=true)
                 AS SELECT record_id AS "id", "rs_f_business_business_code_a053cddd7ba0998b" AS "business_code", "rs_f_business_local_registration_number_8cc04df522908d5c" AS "local_registration_number", "rs_f_business_registered_name_534590704ca0a75d" AS "registered_name", "rs_f_business_administrative_area_91d300b43c158647" AS "administrative_area", "rs_f_business_business_type_063c7320516f2990" AS "business_type"
                    FROM registry_data."rs_e_business_553394fd94e8ee98"
                   WHERE record_lifecycle = 'active';
CREATE VIEW registry_source."establishment"
                 WITH (security_invoker=true, security_barrier=true)
                 AS SELECT record_id AS "id", "rs_f_establishment_establishment_code_e85e4fceaee25f59" AS "establishment_code", "rs_f_establishment_site_name_4d90b2be09442463" AS "site_name", "rs_f_establishment_locality_77665a03f8208a2c" AS "locality", "rs_f_establishment_opened_on_d6dd6244728b9577" AS "opened_on", "rs_f_establishment_establishment_kind_fdd1c4db53d16af3" AS "establishment_kind", "rs_f_establishment_operating_status_fb2774ccb557fbca" AS "operating_status", "rs_f_establishment_preferred_language_e871df790a4ff281" AS "preferred_language"
                    FROM registry_data."rs_e_establishment_77114c253e788b0c"
                   WHERE record_lifecycle = 'active';
CREATE VIEW registry_source."operator_assignment"
                 WITH (security_invoker=true, security_barrier=true)
                 AS SELECT record_id AS "id", "rs_f_operator_assignment_establishment_1639091cfbe5564e" AS "establishment", "rs_f_operator_assignment_business_8e7b11395bfac6a3" AS "business", "rs_f_operator_assignment_relationship_319691f18f6afb93" AS "relationship", "rs_f_operator_assignment_valid_from_8d12dcf77c87d341" AS "valid_from", "rs_f_operator_assignment_valid_to_417d3843a58f8bc6" AS "valid_to"
                    FROM registry_data."rs_e_operator_assignment_79609fb6d027c2ca"
                   WHERE record_lifecycle = 'active';
CREATE VIEW registry_derived."business__establishment_summary"
                     WITH (security_invoker=true, security_barrier=true)
                     AS SELECT "__registry$derived$key" AS "id", "head_office_count"::bigint AS "head_office_count", "branch_count"::bigint AS "branch_count", "production_site_count"::bigint AS "production_site_count", "suspended_site_count"::bigint AS "suspended_site_count", "has_head_office"::boolean AS "has_head_office", "has_production_site"::boolean AS "has_production_site"
                        FROM (
                            SELECT canonical_derived.*,
                                   count(*) OVER (PARTITION BY canonical_derived."__registry$derived$key") AS "__registry$derived$cardinality"
                              FROM (
                                  SELECT trusted_derived.*,
                                         trusted_derived."id"::uuid AS "__registry$derived$key"
                                    FROM (SELECT
  b.id AS id,
  count(e.id) FILTER (WHERE a.relationship = 'head-office')::bigint AS head_office_count,
  count(e.id) FILTER (WHERE a.relationship = 'branch')::bigint AS branch_count,
  count(e.id) FILTER (WHERE e.establishment_kind = 'production')::bigint AS production_site_count,
  count(e.id) FILTER (WHERE e.operating_status = 'suspended')::bigint AS suspended_site_count,
  (count(e.id) FILTER (WHERE a.relationship = 'head-office') > 0) AS has_head_office,
  (count(e.id) FILTER (WHERE e.establishment_kind = 'production') > 0) AS has_production_site
FROM registry_source.business b
LEFT JOIN registry_source.operator_assignment a
  ON a.business = b.id
  AND a.valid_from <= registry_context.evaluation_date()
  AND (a.valid_to IS NULL OR registry_context.evaluation_date() < a.valid_to)
LEFT JOIN registry_source.establishment e
  ON e.id = a.establishment
GROUP BY b.id) AS trusted_derived
                              ) AS canonical_derived
                        ) AS checked_derived
                       WHERE CASE
                           WHEN "__registry$derived$key" IS NOT NULL AND "__registry$derived$cardinality" = 1 THEN true
                           -- PostgreSQL has no scalar ASSERT. This row-dependent
                           -- expression raises one stable, value-free error for
                           -- a null or duplicate canonical key.
                           ELSE 1 / ("__registry$derived$cardinality" - "__registry$derived$cardinality") = 0
                       END;
